validator:
function validate(input) {
  const [{ Fraud = [] }] = input;
  const ids = new Set();
  for (const [id, state, score] of Fraud) {
    if (id === null || state === null || score === null) return 'policy_id, state and fraud_score are required.';
    if (ids.has(id)) return `policy_id ${id} appears twice.`;
    ids.add(id);
    if (score < 0 || score > 1) return 'fraud_score must be between 0 and 1.';
    if (Math.abs(score * 100 - Math.round(score * 100)) > 1e-9) return 'fraud_score has at most two decimals.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const Fraud = [];
  if (size === 'small') {
    // Tiny states and few distinct scores: ties at the top and one-policy states are common.
    const states = ['California', 'Texas', 'New York'];
    const scores = [0.45, 0.77, 0.92, 0.98];
    const count = pick(9);
    for (let i = 0; i < count; i++) Fraud.push([1 + pick(3) + 3 * i, states[pick(states.length)], scores[pick(scores.length)]]);
  } else {
    // About 330 policies per state, so the top 5 percentile spans many ranks and ties around the cut.
    const states = ['California', 'Florida', 'New York', 'Texas', 'Ohio', 'Nevada'];
    for (let id = 1; id <= 2000; id++) Fraud.push([id, states[pick(states.length)], pick(101) / 100]);
  }
  return [{ Fraud }];
}
